BEGIN;
CREATE EXTENSION IF NOT EXISTS pgtap WITH SCHEMA extensions;
SELECT plan(7);
SET LOCAL ROLE authenticated;
SELECT set_config('request.jwt.claims', '{"sub":"a2510000-0000-4000-8000-000000000001","role":"authenticated"}', true);
SELECT is((SELECT count(*) FROM public.audit_logs WHERE changed_by IN ('a2510000-0000-4000-8000-000000000001','a2510000-0000-4000-8000-000000000002','a2510000-0000-4000-8000-000000000003','a2510000-0000-4000-8000-000000000004','a2510000-0000-4000-8000-000000000005','a2510000-0000-4000-8000-000000000006')), 1::bigint, 'P2 member sees own logs only');
SELECT set_config('request.jwt.claims', '{"sub":"a2510000-0000-4000-8000-000000000002","role":"authenticated"}', true);
SELECT is((SELECT count(*) FROM public.audit_logs WHERE changed_by IN ('a2510000-0000-4000-8000-000000000001','a2510000-0000-4000-8000-000000000002','a2510000-0000-4000-8000-000000000003','a2510000-0000-4000-8000-000000000004','a2510000-0000-4000-8000-000000000005','a2510000-0000-4000-8000-000000000006')), 1::bigint, 'P2 leader sees own logs only');
SELECT set_config('request.jwt.claims', '{"sub":"a2510000-0000-4000-8000-000000000003","role":"authenticated"}', true);
SELECT is((SELECT count(*) FROM public.audit_logs WHERE changed_by IN ('a2510000-0000-4000-8000-000000000001','a2510000-0000-4000-8000-000000000002','a2510000-0000-4000-8000-000000000003','a2510000-0000-4000-8000-000000000004','a2510000-0000-4000-8000-000000000005','a2510000-0000-4000-8000-000000000006')), 6::bigint, '会計 sees all fixture logs');
SELECT set_config('request.jwt.claims', '{"sub":"a2510000-0000-4000-8000-000000000004","role":"authenticated"}', true);
SELECT is((SELECT count(*) FROM public.audit_logs WHERE changed_by IN ('a2510000-0000-4000-8000-000000000001','a2510000-0000-4000-8000-000000000002','a2510000-0000-4000-8000-000000000003','a2510000-0000-4000-8000-000000000004','a2510000-0000-4000-8000-000000000005','a2510000-0000-4000-8000-000000000006')), 6::bigint, 'P2 admin sees all fixture logs');
SELECT set_config('request.jwt.claims', '{"sub":"a2510000-0000-4000-8000-000000000005","role":"authenticated"}', true);
SELECT is((SELECT count(*) FROM public.audit_logs WHERE changed_by IN ('a2510000-0000-4000-8000-000000000001','a2510000-0000-4000-8000-000000000002','a2510000-0000-4000-8000-000000000003','a2510000-0000-4000-8000-000000000004','a2510000-0000-4000-8000-000000000005','a2510000-0000-4000-8000-000000000006')), 1::bigint, '部長 sees own logs only');
SELECT set_config('request.jwt.claims', '{"sub":"a2510000-0000-4000-8000-000000000006","role":"authenticated"}', true);
SELECT is((SELECT count(*) FROM public.audit_logs WHERE changed_by IN ('a2510000-0000-4000-8000-000000000001','a2510000-0000-4000-8000-000000000002','a2510000-0000-4000-8000-000000000003','a2510000-0000-4000-8000-000000000004','a2510000-0000-4000-8000-000000000005','a2510000-0000-4000-8000-000000000006')), 1::bigint, '副部長 sees own logs only');
RESET ROLE;
SET LOCAL ROLE anon;
SELECT set_config('request.jwt.claims', '{"role":"anon"}', true);
SELECT is((SELECT count(*) FROM public.audit_logs), 0::bigint, 'anon sees no audit logs');
SELECT * FROM finish();
ROLLBACK;
